      "ref": "[D528]",
      "area": "data",
      "claim": "A parent reports that the app collects driver’s license numbers and other identity documents.",
      "stance": "risk",
      "quote": "the data (family relationships, financial history, foreign contacts) was far more useful for recruiting or blackmail than for fraud."
    },
    {
      "ref": "[D528]",
      "area": "data",
      "claim": "A parent reports that the app stores full scanned images of documents, not just extracted fields.",
      "stance": "risk",
      "quote": "Does the vendor store full document images or only extracted fields?"
    },
    {
      "ref": "[D528]",
      "area": "data",
      "claim": "A parent reports that the app may share data with third parties for advertising or profiling.",
      "stance": "risk",
      "quote": "is treated almost entirely as a consumer-fraud and credit-protection story, even though the scale rivaled what intelligence services would find useful."
    },
    {
      "ref": "[D528]",
      "area": "age_gating",
      "claim": "A parent reports that the app does not enforce an age gate for collecting identity documents.",
      "stance": "neutral",
      "quote": "The 2017 Equifax breach, by contrast, exposed roughly 147 million Americans’ Social Security numbers and was treated almost entirely as a consumer-fraud and credit-protection story, even though the scale rivaled what intelligence services would find useful."
    },
    {
      "ref": "[D528]",
      "area": "content",
      "claim": "A parent reports that the app may expose children to foreign intelligence use of their identity data.",
      "stance": "risk",
      "quote": "A foreign intelligence service doesn’t need to buy the entire 153-million-record set. It needs a small, curated subset, ideally identities matching a specific demographic or geographic profile useful for building long-term cover, and it can acquire that subset quietly, use it slowly, and never trigger the kind of transaction pattern that flags a breach victim’s identity as compromised."
    },
    {
      "ref": "[D528]",
      "area": "developer_record",
      "claim": "A parent reports that the developer has faced regulatory scrutiny for data handling.",
      "stance": "risk",
      "quote": "Under existing U.S. data broker rules, it is unlawful for a data broker to sell sensitive personal data, including driver’s license numbers and passport numbers, to a foreign adversary country or an entity it controls."
    }
  ]
}
